package com.fastkeys1;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.provider.Settings;import android.view.*;import android.widget.*;
public class SteeringOverlayService extends Service{
 WindowManager wm; TextView wheel;
 public void onCreate(){super.onCreate(); if(!Settings.canDrawOverlays(this)){stopSelf();return;} startForeground(71,notification());wm=(WindowManager)getSystemService(WINDOW_SERVICE);wheel=new TextView(this);wheel.setText("↺");wheel.setTextSize(80);wheel.setGravity(Gravity.CENTER);wheel.setTextColor(Color.WHITE);GradientDrawable g=new GradientDrawable();g.setColor(0x663B70D9);g.setShape(GradientDrawable.OVAL);wheel.setBackground(g); WindowManager.LayoutParams p=new WindowManager.LayoutParams(320,320,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,android.graphics.PixelFormat.TRANSLUCENT);p.gravity=Gravity.CENTER;wm.addView(wheel,p);wheel.setOnTouchListener(new View.OnTouchListener(){float sx,sy;int ox,oy;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){sx=e.getRawX();sy=e.getRawY();ox=p.x;oy=p.y;return true;}if(e.getAction()==2){p.x=ox+(int)(e.getRawX()-sx);p.y=oy+(int)(e.getRawY()-sy);wm.updateViewLayout(wheel,p);return true;}if(e.getAction()==1){if(Math.hypot(e.getRawX()-sx,e.getRawY()-sy)<20 && e.getEventTime()-e.getDownTime()<350)stopSelf();return true;}return true;}});}
 private Notification notification(){NotificationChannel ch=new NotificationChannel("steer","Steering",NotificationManager.IMPORTANCE_LOW);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(ch);return new Notification.Builder(this,"steer").setContentTitle("Fast_Keys_1").setContentText("فرمان ماشین فعال است").setSmallIcon(android.R.drawable.ic_menu_directions).build();}
 public android.os.IBinder onBind(Intent i){return null;} public void onDestroy(){if(wheel!=null&&wm!=null)try{wm.removeView(wheel);}catch(Exception ignored){}super.onDestroy();}
}
